/**
 * @file encoder.hpp
 * @brief Core Huffman stream encoder mapping bytes to variable-length prefix bitcodes (JACK-F-004).
 *
 * Implements high-throughput stream and buffer encoding using the prefix codes
 * generated by HuffmanTree and packing them into an io::BitWriter.
 */

#pragma once

#include "huffman_tree.hpp"
#include "io/bit_writer.hpp"
#include <cstdint>
#include <istream>
#include <string>

namespace jackfruit::compression {

/**
 * @brief Summary statistics and status returned upon completing an encoding pass.
 */
struct EncoderResult {
    bool success{false};
    std::string errorMessage;
    uint64_t originalBytes{0};
    uint64_t totalBitsEncoded{0};
    uint64_t compressedBytes{0}; // Number of bytes required by totalBitsEncoded (ceiling(totalBits / 8))
};

/**
 * @brief Core Huffman compression encoder.
 */
class Encoder {
public:
    /**
     * @brief Constructs an Encoder configured with an existing HuffmanTree.
     * @param tree Reference to a populated HuffmanTree containing the prefix codebook.
     */
    explicit Encoder(const HuffmanTree& tree);

    ~Encoder() = default;

    /**
     * @brief Encodes an input binary stream, writing variable-length bits into a BitWriter.
     *
     * Reads in 64 KB buffered chunks for high I/O throughput.
     *
     * @param in Input binary stream to encode.
     * @param writer Reference to BitWriter that will receive the encoded bitstream.
     * @return EncoderResult Statistics including bit count and original byte size.
     */
    EncoderResult encode(std::istream& in, io::BitWriter& writer);

    /**
     * @brief Encodes an in-memory byte buffer into a BitWriter.
     *
     * @param data Pointer to raw byte array.
     * @param size Number of bytes in buffer.
     * @param writer Reference to BitWriter that will receive the encoded bitstream.
     * @return EncoderResult Statistics including bit count and original byte size.
     */
    EncoderResult encode(const uint8_t* data, size_t size, io::BitWriter& writer);

private:
    const HuffmanTree& tree_;
};

} // namespace jackfruit::compression
